const { allowedPrefix } = require("./src/origin");
const tests = [
  "https://trusted.example.com/ok",            // intended
  "https://trusted.example@evil.com/x",        // userinfo bypass -> host evil.com
  "https://trusted.example.evil.com/x",        // lookalike subdomain -> attacker host
  "https://trusted.example.com@169.254.169.254/latest/meta-data/", // SSRF to metadata
  "https://trusted.example/#",                 // path-only
];
for (const u of tests) {
  const passes = allowedPrefix(u);
  let host = "PARSE_FAIL";
  try { host = new URL(u).host; } catch(e){ host = "ERR:"+e.message; }
  console.log(JSON.stringify({url:u, allowlist_passes:passes, parsed_host:host}));
}
'"}

